     * type co-locates the scalar / collection / map behavior that used to be spread across three
     * parallel {@code switch} statements.
     */
    private interface Handler {
        Object resolve(NamedValueMeta meta, HttpRequest request, HttpResponse response);

        Object resolveCollection(NamedValueMeta meta, HttpRequest request, HttpResponse response);

        Object resolveMap(NamedValueMeta meta, HttpRequest request, HttpResponse response);
    }

    private static final Map<ParamType, Handler> HANDLERS = createHandlers();

    private static Map<ParamType, Handler> createHandlers() {
        Map<ParamType, Handler> handlers = new EnumMap<>(ParamType.class);
        return handlers;
    }

    @Override
    protected NamedValueMeta createNamedValueMeta(ParameterMeta param, AnnotationMeta<Annotation> anno) {

