@Activate
public class ParamArgumentResolver extends AbstractAnnotationBaseArgumentResolver {

    /**
     * Resolves a single {@link ParamType} across the three argument shapes. One handler per param
     * type co-locates the scalar / collection / map behavior that used to be spread across three
     * parallel {@code switch} statements.
     */
