@Activate
public class ParamArgumentResolver extends AbstractAnnotationBaseArgumentResolver {

    /**
     * Resolves a single {@link ParamType} across the three argument shapes. One handler per param
     * type co-locates the scalar / collection / map behavior that used to be spread across three
     * parallel {@code switch} statements.
     */
    private interface Handler {
        Object resolve(NamedValueMeta meta, HttpRequest request, HttpResponse response);

        Object resolveCollection(NamedValueMeta meta, HttpRequest request, HttpResponse response);

        Object resolveMap(NamedValueMeta meta, HttpRequest request, HttpResponse response);
    }

    private static final Map<ParamType, Handler> HANDLERS = createHandlers();

    private static Map<ParamType, Handler> createHandlers() {
        Map<ParamType, Handler> handlers = new EnumMap<>(ParamType.class);
        handlers.put(ParamType.PathVariable, new Handler() {
            @Override
            public Object resolve(NamedValueMeta meta, HttpRequest request, HttpResponse response) {
                return resolvePathVariable(meta, request);
            }

            @Override
            public Object resolveCollection(NamedValueMeta meta, HttpRequest request, HttpResponse response) {
                String value = resolvePathVariable(meta, request);
                return value == null ? Collections.emptyList() : Collections.singletonList(value);
            }

            @Override
            public Object resolveMap(NamedValueMeta meta, HttpRequest request, HttpResponse response) {
                String value = resolvePathVariable(meta, request);
                return value == null ? Collections.emptyMap() : Collections.singletonMap(meta.name(), value);
            }
        });
        handlers.put(ParamType.MatrixVariable, new Handler() {
            @Override
            public Object resolve(NamedValueMeta meta, HttpRequest request, HttpResponse response) {
                return CollectionUtils.first(resolveMatrixVariable(meta, request));
            }

            @Override
            public Object resolveCollection(NamedValueMeta meta, HttpRequest request, HttpResponse response) {
                return resolveMatrixVariable(meta, request);
            }

            @Override
            public Object resolveMap(NamedValueMeta meta, HttpRequest request, HttpResponse response) {
                return CollectionUtils.first(resolveMatrixVariable(meta, request));
            }
        });
        handlers.put(ParamType.Param, new Handler() {
            @Override
            public Object resolve(NamedValueMeta meta, HttpRequest request, HttpResponse response) {
                return request.parameter(meta.name());
            }

            @Override
            public Object resolveCollection(NamedValueMeta meta, HttpRequest request, HttpResponse response) {
                return request.parameterValues(meta.name());
            }

            @Override
            public Object resolveMap(NamedValueMeta meta, HttpRequest request, HttpResponse response) {
                return RequestUtils.getParametersMap(request);
            }
        });
        handlers.put(ParamType.Form, new Handler() {
            @Override
            public Object resolve(NamedValueMeta meta, HttpRequest request, HttpResponse response) {
                return request.formParameter(meta.name());
            }

            @Override
            public Object resolveCollection(NamedValueMeta meta, HttpRequest request, HttpResponse response) {
                return request.formParameterValues(meta.name());
            }

            @Override
            public Object resolveMap(NamedValueMeta meta, HttpRequest request, HttpResponse response) {
                return RequestUtils.getFormParametersMap(request);
            }
        });
        handlers.put(ParamType.Header, new Handler() {
            @Override
            public Object resolve(NamedValueMeta meta, HttpRequest request, HttpResponse response) {
                return request.header(meta.name());
            }

            @Override
            public Object resolveCollection(NamedValueMeta meta, HttpRequest request, HttpResponse response) {
                return request.headerValues(meta.name());
            }

            @Override
            public Object resolveMap(NamedValueMeta meta, HttpRequest request, HttpResponse response) {
                return request.headers().asMap();
            }
        });
        handlers.put(ParamType.Cookie, new Handler() {
            @Override
            public Object resolve(NamedValueMeta meta, HttpRequest request, HttpResponse response) {
                return request.cookie(meta.name());
            }

            @Override
            public Object resolveCollection(NamedValueMeta meta, HttpRequest request, HttpResponse response) {
                Collection<HttpCookie> cookies = request.cookies();
                if (cookies.isEmpty()) {
                    return Collections.emptyList();
                }
                String name = meta.name();
                List<HttpCookie> result = new ArrayList<>(cookies.size());
                for (HttpCookie cookie : cookies) {
                    if (name.equals(cookie.name())) {
                        result.add(cookie);
                    }
                }
                return result;
            }

            @Override
            public Object resolveMap(NamedValueMeta meta, HttpRequest request, HttpResponse response) {
                Collection<HttpCookie> cookies = request.cookies();
                if (cookies.isEmpty()) {
                    return Collections.emptyMap();
                }
                Map<String, List<HttpCookie>> mapValue = CollectionUtils.newLinkedHashMap(cookies.size());
                for (HttpCookie cookie : cookies) {
                    mapValue.computeIfAbsent(cookie.name(), k -> new ArrayList<>())
                            .add(cookie);
                }
                return mapValue;
            }
        });
        handlers.put(ParamType.Attribute, new Handler() {
            @Override
            public Object resolve(NamedValueMeta meta, HttpRequest request, HttpResponse response) {
                return request.attribute(meta.name());
            }

            @Override
            public Object resolveCollection(NamedValueMeta meta, HttpRequest request, HttpResponse response) {
                return request.attribute(meta.name());
            }

            @Override
            public Object resolveMap(NamedValueMeta meta, HttpRequest request, HttpResponse response) {
                return request.attributes();
            }
        });
        handlers.put(ParamType.Part, new Handler() {
            @Override
            public Object resolve(NamedValueMeta meta, HttpRequest request, HttpResponse response) {
                return request.part(meta.name());
            }

            @Override
            public Object resolveCollection(NamedValueMeta meta, HttpRequest request, HttpResponse response) {
                return meta.type() == byte[].class ? request.part(meta.name()) : request.parts();
            }

            @Override
            public Object resolveMap(NamedValueMeta meta, HttpRequest request, HttpResponse response) {
                Collection<FileUpload> parts = request.parts();
                if (parts.isEmpty()) {
                    return Collections.emptyMap();
                }
                Map<String, FileUpload> result = new LinkedHashMap<>(parts.size());
                for (FileUpload part : parts) {
                    result.put(part.name(), part);
                }
                return result;
            }
        });
        handlers.put(ParamType.Body, new Handler() {
            @Override
            public Object resolve(NamedValueMeta meta, HttpRequest request, HttpResponse response) {
                if (RequestUtils.isFormOrMultiPart(request)) {
                    return request.formParameter(meta.name());
                }
                return RequestUtils.decodeBody(request, meta.genericType());
            }

            @Override
            public Object resolveCollection(NamedValueMeta meta, HttpRequest request, HttpResponse response) {
                Class<?> type = meta.type();
                if (type == byte[].class) {
                    try {
                        return StreamUtils.readBytes(request.inputStream());
                    } catch (IOException e) {
                        throw new RestException(e);
                    }
                }
                if (RequestUtils.isFormOrMultiPart(request)) {
                    return request.formParameterValues(meta.name());
                }
                return RequestUtils.decodeBody(request, meta.genericType());
            }

            @Override
            public Object resolveMap(NamedValueMeta meta, HttpRequest request, HttpResponse response) {
                if (RequestUtils.isFormOrMultiPart(request)) {
                    return RequestUtils.getFormParametersMap(request);
                }
                return RequestUtils.decodeBody(request, meta.genericType());
            }
        });
        return handlers;
    }

    @Override
    protected NamedValueMeta createNamedValueMeta(ParameterMeta param, AnnotationMeta<Annotation> anno) {
        String defaultValue = anno.getString("defaultValue");
        if (Param.DEFAULT_NONE.equals(defaultValue)) {
            defaultValue = null;
        }
        return new NamedValueMeta(anno.getValue(), anno.getBoolean("required"), defaultValue)
                .setParamType(anno.getEnum("type"));
    }

    @Override
    public Class<Annotation> accept() {
        return Annotations.Param.type();
    }

    @Override
    protected Object resolveValue(NamedValueMeta meta, HttpRequest request, HttpResponse response) {
        Handler handler = HANDLERS.get(meta.paramType());
        if (handler != null) {
            return handler.resolve(meta, request, response);
        }
        switch (meta.paramType()) {
            case PathVariable:
                return resolvePathVariable(meta, request);
            case MatrixVariable:
                return CollectionUtils.first(resolveMatrixVariable(meta, request));
            case Param:
                return request.parameter(meta.name());
            case Form:
                return request.formParameter(meta.name());
            case Header:
                return request.header(meta.name());
            case Cookie:
                return request.cookie(meta.name());
            case Attribute:
                return request.attribute(meta.name());
            case Part:
                return request.part(meta.name());
            case Body:
                if (RequestUtils.isFormOrMultiPart(request)) {
                    return request.formParameter(meta.name());
                }
                return RequestUtils.decodeBody(request, meta.genericType());
        }
        return null;
    }

    @Override
    protected Object filterValue(Object value, NamedValueMeta meta) {
        return StringUtils.EMPTY_STRING.equals(value) ? meta.defaultValue() : value;
    }

    @Override
    protected Object resolveCollectionValue(NamedValueMeta meta, HttpRequest request, HttpResponse response) {
        Handler handler = HANDLERS.get(meta.paramType());
        if (handler != null) {
            return handler.resolveCollection(meta, request, response);
        }
        switch (meta.paramType()) {
            case PathVariable:
                String value = resolvePathVariable(meta, request);
                return value == null ? Collections.emptyList() : Collections.singletonList(value);
            case MatrixVariable:
                return resolveMatrixVariable(meta, request);
            case Param:
                return request.parameterValues(meta.name());
            case Form:
                return request.formParameterValues(meta.name());
            case Header:
                return request.headerValues(meta.name());
            case Cookie:
                Collection<HttpCookie> cookies = request.cookies();
                if (cookies.isEmpty()) {
                    return Collections.emptyList();
                }
                String name = meta.name();
                List<HttpCookie> result = new ArrayList<>(cookies.size());
                for (HttpCookie cookie : cookies) {
                    if (name.equals(cookie.name())) {
                        result.add(cookie);
                    }
                }
                return result;
            case Attribute:
                return request.attribute(meta.name());
            case Part:
                return meta.type() == byte[].class ? request.part(meta.name()) : request.parts();
            case Body:
                Class<?> type = meta.type();
                if (type == byte[].class) {
                    try {
                        return StreamUtils.readBytes(request.inputStream());
                    } catch (IOException e) {
                        throw new RestException(e);
                    }
                }
                if (RequestUtils.isFormOrMultiPart(request)) {
                    return request.formParameterValues(meta.name());
                }
                return RequestUtils.decodeBody(request, meta.genericType());
        }
        return null;
    }

    @Override
    protected Object resolveMapValue(NamedValueMeta meta, HttpRequest request, HttpResponse response) {
        Handler handler = HANDLERS.get(meta.paramType());
        if (handler != null) {
            return handler.resolveMap(meta, request, response);
        }
        switch (meta.paramType()) {
            case PathVariable:
                String value = resolvePathVariable(meta, request);
                return value == null ? Collections.emptyMap() : Collections.singletonMap(meta.name(), value);
            case MatrixVariable:
                return CollectionUtils.first(resolveMatrixVariable(meta, request));
            case Param:
                return RequestUtils.getParametersMap(request);
            case Form:
                return RequestUtils.getFormParametersMap(request);
            case Header:
                return request.headers().asMap();
            case Cookie:
                Collection<HttpCookie> cookies = request.cookies();
                if (cookies.isEmpty()) {
                    return Collections.emptyMap();
                }
                Map<String, List<HttpCookie>> mapValue = CollectionUtils.newLinkedHashMap(cookies.size());
                for (HttpCookie cookie : cookies) {
                    mapValue.computeIfAbsent(cookie.name(), k -> new ArrayList<>())
                            .add(cookie);
                }
                return mapValue;
            case Attribute:
                return request.attributes();
            case Part:
                Collection<FileUpload> parts = request.parts();
                if (parts.isEmpty()) {
                    return Collections.emptyMap();
                }
                Map<String, FileUpload> result = new LinkedHashMap<>(parts.size());
                for (FileUpload part : parts) {
                    result.put(part.name(), part);
                }
                return result;
            case Body:
                if (RequestUtils.isFormOrMultiPart(request)) {
                    return RequestUtils.getFormParametersMap(request);
                }
                return RequestUtils.decodeBody(request, meta.genericType());
        }
        return null;
    }

    private static String resolvePathVariable(NamedValueMeta meta, HttpRequest request) {
        Map<String, String> variableMap = request.attribute(RestConstants.URI_TEMPLATE_VARIABLES_ATTRIBUTE);
        if (variableMap == null) {
            if (meta.required()) {
                throw new RestParameterException(Messages.ARGUMENT_VALUE_MISSING, meta.name(), meta.type());
            }
            return null;
        }
        String value = variableMap.get(meta.name());
        if (value == null) {
            return null;
        }
        int index = value.indexOf(';');
        return RequestUtils.decodeURL(index == -1 ? value : value.substring(0, index));
    }

    private static List<String> resolveMatrixVariable(NamedValueMeta meta, HttpRequest request) {
        Map<String, String> variableMap = request.attribute(RestConstants.URI_TEMPLATE_VARIABLES_ATTRIBUTE);
        return RequestUtils.parseMatrixVariableValues(variableMap, meta.name());
    }
}

