@Activate
public class ParamArgumentResolver extends AbstractAnnotationBaseArgumentResolver {

    /**
     * Resolves a single {@link ParamType} across the three argument shapes. One handler per param
     * type co-locates the scalar / collection / map behavior that used to be spread across three
     * parallel {@code switch} statements.
     */
    private interface Handler {
        Object resolve(NamedValueMeta meta, HttpRequest request, HttpResponse response);

        Object resolveCollection(NamedValueMeta meta, HttpRequest request, HttpResponse response);

        Object resolveMap(NamedValueMeta meta, HttpRequest request, HttpResponse response);
    }

    private static final Map<ParamType, Handler> HANDLERS = createHandlers();

    private static Map<ParamType, Handler> createHandlers() {
        Map<ParamType, Handler> handlers = new EnumMap<>(ParamType.class);
        handlers.put(ParamType.PathVariable, new Handler() {
            @Override
            public Object resolve(NamedValueMeta meta, HttpRequest request, HttpResponse response) {
                return resolvePathVariable(meta, request);
            }

            @Override
            public Object resolveCollection(NamedValueMeta meta, HttpRequest request, HttpResponse response) {
                String value = resolvePathVariable(meta, request);
                return value == null ? Collections.emptyList() : Collections.singletonList(value);
            }

            @Override
            public Object resolveMap(NamedValueMeta meta, HttpRequest request, HttpResponse response) {
                String value = resolvePathVariable(meta, request);
                return value == null ? Collections.emptyMap() : Collections.singletonMap(meta.name(), value);
            }
        });
        handlers.put(ParamType.MatrixVariable, new Handler() {
            @Override
            public Object resolve(NamedValueMeta meta, HttpRequest request, HttpResponse response) {
                return CollectionUtils.first(resolveMatrixVariable(meta, request));
            }

            @Override
            public Object resolveCollection(NamedValueMeta meta, HttpRequest request, HttpResponse response) {
                return resolveMatrixVariable(meta, request);
            }

            @Override
            public Object resolveMap(NamedValueMeta meta, HttpRequest request, HttpResponse response) {
                return CollectionUtils.first(resolveMatrixVariable(meta, request));
            }
        });
        handlers.put(ParamType.Param, new Handler() {
            @Override
            public Object resolve(NamedValueMeta meta, HttpRequest request, HttpResponse response) {
                return request.parameter(meta.name());
            }

            @Override
            public Object resolveCollection(NamedValueMeta meta, HttpRequest request, HttpResponse response) {
                return request.parameterValues(meta.name());
            }

            @Override
            public Object resolveMap(NamedValueMeta meta, HttpRequest request, HttpResponse response) {
                return RequestUtils.getParametersMap(request);
            }
        });
        handlers.put(ParamType.Form, new Handler() {
            @Override
            public Object resolve(NamedValueMeta meta, HttpRequest request, HttpResponse response) {
                return request.formParameter(meta.name());
            }

            @Override
            public Object resolveCollection(NamedValueMeta meta, HttpRequest request, HttpResponse response) {
                return request.formParameterValues(meta.name());
            }

            @Override
            public Object resolveMap(NamedValueMeta meta, HttpRequest request, HttpResponse response) {
                return RequestUtils.getFormParametersMap(request);
            }
        });
        handlers.put(ParamType.Header, new Handler() {
            @Override
            public Object resolve(NamedValueMeta meta, HttpRequest request, HttpResponse response) {
                return request.header(meta.name());
            }

            @Override
            public Object resolveCollection(NamedValueMeta meta, HttpRequest request, HttpResponse response) {
                return request.headerValues(meta.name());
            }

            @Override
            public Object resolveMap(NamedValueMeta meta, HttpRequest request, HttpResponse response) {
                return request.headers().asMap();
            }
        });
        handlers.put(ParamType.Cookie, new Handler() {
            @Override
            public Object resolve(NamedValueMeta meta, HttpRequest request, HttpResponse response) {
                return request.cookie(meta.name());
            }

            @Override
            public Object resolveCollection(NamedValueMeta meta, HttpRequest request, HttpResponse response) {
                Collection<HttpCookie> cookies = request.cookies();
                if (cookies.isEmpty()) {
                    return Collections.emptyList();
                }
                String name = meta.name();
                List<HttpCookie> result = new ArrayList<>(cookies.size());
                for (HttpCookie cookie : cookies) {
                    if (name.equals(cookie.name())) {
                        result.add(cookie);
                    }
                }
                return result;
            }

            @Override
            public Object resolveMap(NamedValueMeta meta, HttpRequest request, HttpResponse response) {
                Collection<HttpCookie> cookies = request.cookies();
                if (cookies.isEmpty()) {
                    return Collections.emptyMap();
                }
                Map<String, List<HttpCookie>> mapValue = CollectionUtils.newLinkedHashMap(cookies.size());
                for (HttpCookie cookie : cookies) {
